# Test the TocToken class approach
from collections import UserDict

class TocToken(UserDict):
    EXTRA_KEYS = {'html', 'data-toc-label'}

    def __eq__(self, other):
        if isinstance(other, dict):
            # Compare only the core keys
            for key in ('level', 'id', 'name', 'children'):
                if self.get(key) != other.get(key):
                    return False
            return True
        return super().__eq__(other)

    def __ne__(self, other):
        return not self.__eq__(other)

# Test it
t = TocToken({'level': 1, 'id': 'foo-bar', 'name': 'Foo &amp; bar', 'html': '<div>Foo &amp; bar</div>', 'data-toc-label': None, 'children': []})
expected = {'level': 1, 'id': 'foo-bar', 'name': 'Foo &amp; bar', 'children': []}
print(f"Equality test: {t == expected}")
print(f"Keys: {list(t.keys())}")
print(f"name: {t['name']}")
print(f"html: {t['html']}")
print(f"data-toc-label: {t['data-toc-label']}")

